require __DIR__.'/../src/bootstrap.php';
ini_set('session.use_strict_mode','1');session_set_cookie_params(['httponly'=>true,'secure'=>true,'samesite'=>'Lax']);session_start();$_SESSION['research_csrf']??=bin2hex(random_bytes(32));$message='';$device=false;
try{secureDevice();$device=tutorDevice();attRequire((bool)$device,'Open this page on your enrolled attendance phone. Ask Admin for a phone enrolment link if needed.');if($_SERVER['REQUEST_METHOD']==='POST'){attRequire(hash_equals($_SESSION['research_csrf'],$_POST['csrf']??''),'Refresh this page and try again.');db()->beginTransaction();rescheduleOwnSession($device['staff'],$_POST);db()->commit();$message='Session updated for every participating group.';}}catch(Throwable $ex){if(db()->inTransaction())db()->rollBack();$message=$ex instanceof PDOException?'Unable to save. Contact Admin.':$ex->getMessage();}
?><!doctype html><html><head><meta name="viewport" content="width=device-width, initial-scale=1"><title>My flexible teaching sessions</title><link rel="stylesheet" href="assets/style.css"></head><body><main style="max-width:850px;margin:auto;padding:20px"><h1>My flexible teaching sessions</h1><p><?=e($message)?></p><?php if($device):?><p>Change the actual date, time or classroom of your future research sessions. Combined groups move together. Attendance exemptions are controlled by Admin/DAA.</p><?php foreach(scheduledRows()as $t):if((int)$t['staff_id']!==(int)$device['staff']['id']||!$t['active']||empty($t['flexible']))continue;?><section class="card"><h2><?=e($t['subject_code'].' · '.sessionLabel($t,'programme'))?></h2><p><?=e($t['delivery_mode'].' · Attendance '.($t['attendance_required']?'required':'not required'))?></p><?php if(!$t['class_date']||strtotime($t['class_date'].' '.$t['start_time'])<=time()):?><p>This session cannot be edited here. Ask DAA to schedule future specific-date sessions.</p><?php else:?><form method="post"><input type="hidden" name="csrf" value="<?=e($_SESSION['research_csrf'])?>"><input type="hidden" name="id" value="<?=$t['id']?>"><div class="form-grid"><?php foreach(['class_date'=>'date','start_time'=>'time','end_time'=>'time']as $k=>$type):?><label><?=e(ucwords(str_replace('_',' ',$k)))?><input required type="<?=$type?>" name="<?=$k?>" value="<?=e($t[$k])?>"></label><?php endforeach;if($t['delivery_mode']!=='Online'):?><label>Classroom<select name="classroom_id" required><?php foreach(all('SELECT id,room_code FROM classrooms WHERE active=1')as $r):?><option value="<?=$r['id']?>" <?=$r['id']==$t['classroom_id']?'selected':''?>><?=e($r['room_code'])?></option><?php endforeach;?></select></label><?php endif;?></div><button>Save timing</button></form><?php endif;?></section><?php endforeach;endif;?></main></body></html>
